#!/usr/bin/env python3
# NOTICE: substantially generated by an LLM coding system.

"""Build the Chicago air quality CSVs from the Open Air Chicago sensor network.

The source dataset holds every individual measurement from the whole network
and is far too large to commit: about 12 million rows, growing by roughly
72,000 a day. This script pulls one calendar month across all sensors and
splits it into two files:

  chicago-air-quality-<MONTH>.csv.gz  one row per measurement, keyed by sensor_id
  chicago-air-quality-sensors.csv     one row per sensor: name, community area, location

Set MONTH below to build a different month. The newest days upstream are still
filling in (see the README), so leave the most recent month or so alone.
"""

from calendar import monthrange
from datetime import date
from pathlib import Path
import csv
import gzip
import re

import requests

# The month to build, "YYYY-MM". One month of measurements is about 2.2 million
# rows, ~155 MB as plain CSV, so the output is gzipped; pandas reads .csv.gz
# directly. Building more than a month at a time is not recommended.
MONTH = "2026-07"

BASE = Path(__file__).resolve().parent
OUT_MEASUREMENTS = BASE / f"chicago-air-quality-{MONTH}.csv.gz"
OUT_SENSORS = BASE / "chicago-air-quality-sensors.csv"

SOCRATA = "https://data.cityofchicago.org/resource"
DATASET_ID = "xfya-dxtq"

HEADERS = {"User-Agent": "data-adventures-dataset-script/1.0"}

PAGE_SIZE = 50000

# About 1 m. A sensor is bolted to a pole, so more precision is just bytes.
COORD_DECIMALS = 5

# Source fields requested. Left out on purpose:
#   bc*                          all black carbon modules are offline (100% empty)
#   atmpressure*, wind*, *ambient*   only the few sensors with weather modules
#                                report these (<1% of rows)
#   pm2_5concnumindividual_raw   equals the calibrated value on 98% of rows
#   location, :@computed_region_*    redundant with latitude/longitude
#   record_id                    just datasourceid + the timestamp to the minute
FIELDS = [
    "datasourceid",
    "sensor_name",
    "time",
    "pm2_5concmassindividual_value",
    "pm2_5concmassindividual_raw",
    "no2concindividual_value",
    "no2concindividual_raw",
    "pm2_5concnumindividual_value",
    "temperatureinternalindividual",
    "relhumidinternalindividual",
]

# sensor_name and the sensor's coordinates are constant per sensor, so they
# live in the lookup file rather than repeating on every measurement row.
MEASUREMENT_COLUMNS = [
    "sensor_id",
    "time_utc",
    "pm2_5",
    "pm2_5_raw",
    "no2",
    "no2_raw",
    "pm2_5_number",
    "temperature_c",
    "relative_humidity",
]

SENSOR_COLUMNS = [
    "sensor_id",
    "sensor_name",
    "community_area",
    "latitude",
    "longitude",
    "measurements",
]

# sensor_name is a community area followed by that sensor's number within it,
# e.g. "Archer Heights 2".
SENSOR_NUMBER_RE = re.compile(r"\s+\d+$")


def month_window():
    year, month = (int(p) for p in MONTH.split("-"))
    start = date(year, month, 1)
    return start, date(year, month, monthrange(year, month)[1])


def fetch(start, stop):
    """All measurements in [start, stop], paged. Both bounds inclusive."""
    rows = []
    while True:
        resp = requests.get(
            f"{SOCRATA}/{DATASET_ID}.json",
            params={
                "$select": ",".join(FIELDS + ["latitude", "longitude"]),
                "$where": f"time >= '{start}T00:00:00' AND time < '{stop}T00:00:00'",
                "$order": ":id",
                "$limit": PAGE_SIZE,
                "$offset": len(rows),
            },
            headers=HEADERS,
            timeout=300,
        )
        resp.raise_for_status()
        batch = resp.json()
        rows.extend(batch)
        print(f"    {len(rows)} rows")
        if len(batch) < PAGE_SIZE:
            return rows


def num(value, decimals=2):
    if value in (None, ""):
        return ""
    return f"{float(value):.{decimals}f}"


def main():
    start, last = month_window()
    stop = date(last.year + (last.month == 12), last.month % 12 + 1, 1)
    print(f"Fetching {MONTH}, {start} through {last}...")
    raw = fetch(start, stop)

    measurements = []
    sensors = {}
    for r in raw:
        sensor_id = r.get("datasourceid", "")
        name = r.get("sensor_name", "")
        measurements.append(
            [
                sensor_id,
                # Socrata returns e.g. 2026-07-20T00:00:01.092; sub-second
                # precision is noise on a sensor sampling every ~3 minutes.
                (r.get("time") or "")[:19],
                num(r.get("pm2_5concmassindividual_value")),
                num(r.get("pm2_5concmassindividual_raw")),
                num(r.get("no2concindividual_value")),
                num(r.get("no2concindividual_raw")),
                num(r.get("pm2_5concnumindividual_value")),
                num(r.get("temperatureinternalindividual")),
                num(r.get("relhumidinternalindividual")),
            ]
        )
        sensor = sensors.setdefault(
            sensor_id,
            [
                sensor_id,
                name,
                SENSOR_NUMBER_RE.sub("", name),
                num(r.get("latitude"), COORD_DECIMALS),
                num(r.get("longitude"), COORD_DECIMALS),
                0,
            ],
        )
        sensor[-1] += 1

    with gzip.open(OUT_MEASUREMENTS, "wt", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(MEASUREMENT_COLUMNS)
        # Sorted by time, then sensor, so a given month always writes in the
        # same order regardless of how the API paged it.
        writer.writerows(sorted(measurements, key=lambda r: (r[1], r[0])))

    with open(OUT_SENSORS, "w", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(SENSOR_COLUMNS)
        writer.writerows(sorted(sensors.values(), key=lambda r: r[1]))

    for path, n in ((OUT_MEASUREMENTS, len(measurements)), (OUT_SENSORS, len(sensors))):
        print(f"  {path.name}: {n} rows, {path.stat().st_size / 1e6:.1f} MB")


if __name__ == "__main__":
    main()
